function IkonDinamis({ nama, size = 24, className, ...rest }: IkonProps & { nama: string }) {
  const { iconSet } = useTheme();
  const C = (SET[iconSet] ?? SET.lucide)[nama] ?? SET.lucide[nama];
  return (
    <C
      width={size}
      height={size}
      className={className ? `simpes-ikon ${className}` : 'simpes-ikon'}
      aria-hidden="true"
      focusable="false"
      {...rest}
    />
  );
}

